  if (teljes) p.tunderharmat = (p.tunderharmat || 0) + HET_TELJES_HARMAT;   /* 🌟 teljes hét (rajzterv B, 3. döntés: most 💧, később csemege) */
  HET_UJ = { k: k, n: n, teljes: teljes, nap: ma, mondva: 0 };
