  if (F.ful === "nyul") s += fgTk('<g transform="rotate(-10 38 40)"><ellipse cx="38" cy="22" rx="8" ry="19" fill="' + b + '"' + fgKv(d) + '/><ellipse cx="38" cy="24" rx="4" ry="14" fill="#f7b6c8"/></g>');
