var M_SZ = { mm: 1, cm: 10, dm: 100, m: 1000, km: 1e6, ml: 1, cl: 10, dl: 100, l: 1000, hl: 1e5, g: 1, dkg: 10, kg: 1000, q: 1e5, t: 1e6 };
