function mFinomabb(a, b) { return M_SZ[a] < M_SZ[b]; }

/* ── számok kiírása és kimondása 100 000-ig ── */
function mSzamIr(n) { return n >= 10000 ? String(n).replace(/\B(?=(\d{3})+(?!\d))/g, " ") : String(n); }
