  if (n < 1000) return mSzazSzo(n);
  var e = Math.floor(n / 1000), r = n % 1000;
  return (e === 1 ? "" : mSzazSzo(e).replace(/kettő$/, "két")) + "ezer" + (r ? (n > 2000 ? "-" : "") + mSzazSzo(r) : "");
