    + '<path d="M8 -34 q-3 -10 6 -12 q9 2 6 12 q-3 3 -6 1 q-3 2 -6 -1 Z" fill="#ff6b6b"/>';
  if (id === "gombak") return arny.replace("RX", 24).replace("RY", 6)
    + '<rect x="-12" y="-16" width="9" height="16" rx="4" fill="#f6ecd6"/>'
