    + '<path d="M16 -40 c-5 0 -7 8 -1 12 c2 1 4 0 5 0 c1 0 3 1 5 0 c6 -4 4 -12 -1 -12 c-2 0 -3 1 -4 1 c-1 0 -2 -1 -4 -1 Z"/>'
    + '</g>'
