    s += '<path d="M' + ktP(tet[0][0], tet[0][1], "C", tet[1][0], tet[1][1], tet[2][0], tet[2][1], tet[3][0], tet[3][1]) + '" stroke="#ecc996" stroke-width="4" fill="none" stroke-linecap="round"/>';
