  if (sel) for (i = 0; i < old.length; i++)
    for (j = 0; j < old[i].tetelek.length; j++) {
      var e = old[i].tetelek[j];
      if (e.cs.kulcs === sel.g && String(e.t.id) === String(sel.id)) return i;
    }
